INSERT INTO `conditions_acces` (`id`, `condition_texte`) VALUES
(1, 'Pour s’inscrire en Doctorat, le candidat doit être titulaire d’un :\r\n\r\nMaster,\r\nMaster Sciences et Techniques,\r\nMaster spécialisé,\r\nDiplôme d’ingénieur d’état.\r\nA titre exceptionnel, des dérogations peuvent être accordées aux titulaires d’un diplôme reconnu équivalent, ou l’un des diplômes nationaux dont la liste est fixée par arrêté de l’autorité gouvernementale chargée de l’enseignement supérieur.\r\n\r\nPré-requis de compétences scientifiques d’accès à la formation doctorale :\r\n\r\nLes candidats doivent avoir les diplômes, précédemment cités, dans les disciplines suivantes : Mathématiques, Sciences et Techniques de l’information et de la communication, Télécommunications, Génie électrique, Génie mécanique et maintenance, Génie industriel, Informatique.\r\n\r\nLes candidats doivent justifier d’un cursus universitaire en adéquation avec le profil de la formation doctorale.'),
(2, 'Diplômes requis :\r\n\r\nPour s’inscrire en Doctorat, le candidat doit être titulaire d’un :\r\n\r\n–             Master,\r\n\r\n–             Master Sciences et Techniques,\r\n\r\n–             Master spécialisé,\r\n\r\n–             Diplôme d’ingénieur d’état.\r\n\r\nA titre exceptionnel, des dérogations peuvent être accordées aux titulaires d’un diplôme reconnu équivalent, ou l’un des diplômes nationaux dont la liste est fixée par arrêté de l’autorité gouvernementale chargée de l’enseignement supérieur.\r\n\r\n\r\nPré-requis de compétences scientifiques d’accès à la formation doctorale :\r\n  Les candidats doivent avoir les diplômes, précédemment cités, dans les disciplines suivantes : Mathématiques, Sciences et Techniques de l’information et de la communication, \r\n  Télécommunications, Génie électrique, Génie mécanique et maintenance, Génie industriel, Informatique.\r\n   Les candidats doivent justifier d’un cursus universitaire en adéquation avec le profil de la formation doctorale.'),
(3, 'Diplômes requis\r\n\r\n–         Master\r\n\r\n–         Médecine\r\n\r\n–         Médecine dentaire\r\n\r\n–         Pharmacie\r\n\r\n–         Médecine vétérinaire\r\n\r\n–         Autres diplômes équivalents (ingénieur d’état)\r\n\r\n \r\n\r\nPré-requis scientifiques et pédagogiques :\r\n\r\nLa formation doctorale présentée s’articule avec les filières de master de l’Université.\r\n\r\nA l’échelle de l’Université les filières citées ci-dessous devraient alimenter cette formation doctorale :\r\n\r\n–         MASTERS (Faculté des Sciences Dhar El Maharaz Fès)\r\n\r\no   Physiologie pharmacologie et sciences biomédicales\r\n\r\n–         MASTERS SCIENCES ET TECHNIQUES (FST de Fès)\r\n\r\no   Chimie des molécules bioactives.\r\n\r\no   Biotechnologie microbienne.\r\n\r\no   Gestion et conservation de la biodiversité.\r\n\r\no   Hydrologie de surface et qualité des eaux\r\n\r\no   Systèmes Microélectronique de Télécommunication et de l’informatique Industriel\r\n\r\no   Réseaux et Systèmes Intelligents\r\n\r\n \r\n\r\n–         Doctorat Médecine et Pharmacie :\r\n\r\no   Doivent justifier d’une expérience dans les axes de recherches couverts par la formation doctorale pour bénéficier d’une dérogation accordée par le responsable de la formation doctorale et du directeur de thèse.\r\n\r\n \r\n\r\n–         Diplômes d’Ingénieurs de l’ENSA\r\n\r\no   Génie Industriel\r\n\r\no   Génie Informatique\r\n\r\no   Génie Télécommunications& Réseau\r\n\r\no   Génie des systèmes Embarqués et informatique Industrielle\r\n\r\n \r\n\r\n–         Diplômes d’Ingénieurs de la FST\r\n\r\no   Industries Agricoles et Alimentaires\r\n\r\n \r\n\r\nLes lauréats de ces différentes filières auront la possibilité de continuer leurs études au sein de cette formation doctorale. La formation doctorale accueillera aussi les lauréats d’autres filières Masters et filières d’ingénieurs d’état dans des thématiques équivalentes, accrédités à l’échelle nationale.'),
(4, 'Diplômes requis :\r\nPour s’inscrire en Doctorat, le candidat doit être titulaire d’un\r\n\r\nDiplôme d’ingénieur d’état\r\nMaster,\r\nMaster Sciences et Techniques,\r\nou d’un diplôme reconnu équivalent.\r\nA titre exceptionnel, des dérogations peuvent être accordées aux titulaires d’un Master Spécialisé ou d’un diplôme reconnu équivalent, ou l’un des diplômes nationaux dont la liste sera fixée par arrêté de l’autorité gouvernementale chargée de l’enseignement supérieur.\r\n\r\nLa dérogation est accordée selon la norme D2, définie dans le Cahier des Normes Pédagogiques National.\r\n\r\n \r\n\r\nPré-requis scientifiques et pédagogiques\r\nLes candidats doivent avoir les diplômes, précédemment cités, dans les disciplines scientifiques et de l’ingénieur.\r\n\r\nLes candidats doivent justifier d’un cursus universitaire en adéquation avec le profil de la formation doctorale.'),
(5, 'Diplômes requis :\r\n\r\nPour s’inscrire en Doctorat, le candidat doit être titulaire d’un Master, Master Spécialisé, Master Sciences et Techniques ou d’un diplôme reconnu équivalent.\r\n\r\nPrérequis des compétences scientifiques :\r\n\r\nLes candidats doivent avoir les diplômes, précédemment cités, dans des disciplines cohérentes avec l’axe de recherche souhaité'),
(6, 'Diplômes requis :\r\n\r\nPour s’inscrire en Doctorat, le candidat doit être titulaire d’un\r\n\r\n– Master,\r\n\r\n– Master Sciences et Techniques,\r\n\r\n– ou d’un diplôme reconnu équivalent.\r\n\r\nPrérequis de compétences scientifiques d’accès à la formation doctorale :\r\n\r\nLes candidats doivent avoir les diplômes, précédemment cités, dans les disciplines suivantes : Mathématiques, Sciences et Techniques de l’information et de la communication, Télécommunications, Génie électrique,\r\n Génie mécanique et maintenance, Génie industriel, Informatique, Biologie, Chimie, Géologie, Bioinformatique. Les candidats doivent justifier d’un cursus universitaire en adéquation avec le profil de la formation doctorale.'),
(7, 'Critères sur le diplôme et la spécialité :\r\n\r\nPour s’inscrire en Doctorat, le candidat doit être titulaire d’un Master, Master spécialisé, ou d’un diplôme reconnu équivalent.\r\n\r\n \r\n\r\nPrérequis de compétences scientifiques d’accès à la formation doctorale : \r\n\r\n Les candidats doivent avoir les diplômes, précédemment cités, dans les disciplines susmentionnées. \r\n Le Diplôme requis doit être obtenu au moins avec la mention Assez Bien. Les candidats doivent justifier \r\n d’un cursus universitaire leur permettant de mener à terme une recherche doctorale dans les domaines de cette formation.\r\n\r\n \r\n\r\n \r\n\r\n \r\n\r\nCritères devant être attestés par entretien direct avec les candidats :\r\n\r\nDans le cas où le candidat est présélectionné, il sera convoqué pour passer un entretien oral devant un jury \r\ncomposé des enseignants faisant partie du laboratoire de recherche. Chaque jury sera constitué d’enseignants encadrants \r\n(directeurs de thèse) dont les spécialités s’insèrent dans un axe thématique donné. Le président du jury peut convoquer un ou deux enseignants \r\nfaisant partie du laboratoire et dont la spécialité concorde avec l’axe thématique.\r\n\r\nLes critères qui seront pris en compte seront les suivants :\r\n\r\n– sens d’organisation et enchainement logique des idées ;\r\n\r\n– qualité de l’argumentation ;\r\n\r\n– Motivation et engagement pour la recherche\r\n\r\n– esprit critique et réflexivité\r\n\r\n– maitrise des langues.'),
(8, 'الشهادات المطلوبة:  شهادة الماستر  (أو ما يعادلها)\r\n\r\n2.4 متطلبات المهارات العلمية لولوج التكوين في سلك الدكتوراه:\r\n\r\n– استيفاء جميع وحدات الماستر\r\n\r\n     – معرفة جيدة باللغة العربية\r\n\r\n     – إتقان لغة أجنبية واحدة على الأقل\r\n\r\n3.4. معايير ومساطر الانتقاء:\r\n\r\nدراسة الملف: الميزات على الأقل 12/20 في شهادة الماستر، نقط المواد الأساسية المعتمدة في الماستر، عدد سنوات الدراسة\r\nمقابلة لاستطلاع مؤهلات المترشح في المعارف المطلوبة لمتابعة دراسات الدكتوراه'),
(9, 'Il s’agit des diplômes mentionnés dans l’arrêté du ministre de l’éducation nationale, de l’enseignement supérieur, de la formation des cadres et de la recherche scientifique, n° 140-09 du 25 moharrem 1430 (22 janvier 2009) fixant la liste des diplômes nationaux permettant l’accès aux formations du cycle du doctorat. Il s’agit des Masters :\r\n\r\n–Sciences du langage\r\n\r\n–Sciences cognitives\r\n\r\n–Littératures (littérature comparée, études culturelles (identité, ethnicité, genre,représentations culturelles)\r\n\r\n–Didactique\r\n\r\n–Terminologie et traduction\r\n\r\n–Gender studies\r\n\r\n– Language, communication ans society\r\n\r\n–Translation and Cross-Cultural communication\r\n\r\n–Applied Language Studies and Reaserch in Higher Education.\r\n\r\n–Cultural studies : Cultures, Idendities and Nationhood in Morocco.\r\n\r\n–تحالف الحضارات و حوار الأديان\r\n\r\n–اللسانيات وعلوم اللغة\r\n\r\n–الأدب القديم بمختلف تخصصاته\r\n\r\n–الأدب الحديث بمختلف تخصصاته\r\n\r\n–الأدب المغربي والأندلسي\r\n\r\nتخصصات العلوم الإنسانية\r\n\r\n \r\n\r\n4.2.Pré-requis de compétences scientifiques d’accès à la formation doctorale\r\n\r\n-Très bonne maîtrise de la langue de travail qui sera utilisée pour la rédaction de la thèse.\r\n\r\n-Très bonne connaissances en cultures en littératures, en sciences du langage, en sciences cognitives, en didactique/pédagogie universitaire, en communication.\r\n\r\n-Très bon savoir-faire en matière de recherche documentaire, de méthodologie de la recherche et de la manipulation des nouvelles technologies.\r\n\r\n-Bonne culture générale\r\n\r\n \r\n\r\n4.3. Critères et procédures de sélection :\r\n\r\nEtude du dossier:\r\n(Expliciter les critères de sélection: mentions, nombre d’années d’études, notes des modules et des connaissances fondamentales, etc…)\r\n\r\n–Mention en licence  et au Master (Assez Bien ou plus).\r\n\r\n–Notes des Modules majeurs en Master  (≥ 12).\r\n\r\n–Rapport de thèse. Projet de thèse détaillé.\r\n\r\n–Lettre de motivation.\r\n\r\n–Lettre(s) de recommandation.\r\n\r\n–Accord du responsable de la structure de recherche d’accueil\r\n\r\n \r\n\r\nEntretien :\r\nLes candidats présélectionnés seront soumis à un entretien oral (30 min. environ) permettant de tester leurs :\r\n\r\n–Connaissances, tant générales que spécifiques à la formation en linguistique en littérature, traduction, sciences cognitives, didactique de l’enseignement des langues et des cultures, pédagogie universitaire) ;\r\n\r\n–Motivations ;\r\n\r\n–Aptitudes et capacités à suivre une formation doctorale et à conduire des recherches débouchant sur la réalisation d’une thèse de Doctorat.\r\n\r\netc.\r\n\r\nExamen écrit\r\nAutres (spécifier):'),
(10, 'Afin de s’inscrire à cette formation doctorale l’étudiant doit présenter l’un des diplômes suivants :\r\n\r\nUn diplôme de Master, un diplôme d’Études Approfondies (DEA) ou équivalent, en Histoire, Études Islamiques ou dans une discipline liée au domaine de formation.\r\nUn Master en Relations Internationales peut être accepté pour une inscription dans le volet Histoire.\r\nConnaissances scientifiques et pédagogiques requises :\r\n\r\nFondamentaux de la communication et de l’expression linguistique.\r\nBases en analyse et synthèse.\r\nAutres compétences personnelles utiles.\r\nBases en informatique.\r\nProcédure de sélection :\r\n\r\nExamen du dossier (critères : mentions obtenues, nombre d’années d’études, notes dans les matières principales).\r\nEntretien scientifique évaluant la cohérence du parcours académique et la motivation.\r\nPrésentation d’un projet préliminaire de recherche.'),
(11, 'Diplômes requis :\r\n\r\nUn diplôme de Master dans la spécialité proposée, un diplôme d’Études Approfondies (DEA) ou un équivalent.\r\nConnaissances scientifiques et pédagogiques requises :\r\n\r\nFondamentaux de la communication et de l’expression linguistique.\r\nBases en analyse et synthèse.\r\nCompétences académiques complémentaires.\r\nBases en informatique.\r\nProcédure de sélection :\r\n\r\nProjet de thèse : Présentation d’un projet de recherche préliminaire.\r\nExamen du dossier (critères : mentions obtenues, nombre d’années d’études, notes dans les matières principales, etc.).\r\nEntretien avec le comité spécialisé de la structure d’accueil.'),
(12, 'Les étudiants admis à suivre ce doctorat doivent avoir un DESA, un Master en géographie (toute spécialités confondues) ou dans les disciplines connexes ayant un intérêt pour l’aménagement du territoire et le développement local comme en économie, sciences de la terre et de la matière, biologie, foresterie, hydrologie, sociologie et diplôme équivalent. Les diplômes d’Ingénieur d’Etat seront aussi admis dans les disciplines connexes comme l’architecture, le génie civil ou toute autre discipline jugée utile par un comité d’experts, qui sera formé au sein du centre. Ce comité est habilité à juger l’équivalence au Master de tout autres diplômes présentés par les candidats.\r\n\r\nConnaissances scientifiques et pédagogiques requises :\r\n\r\n·        Fondamentaux de la compréhension du territoire dans une perspective géographique, scientifique ou technique.\r\n\r\n·        Bases de la communication, de l’expression linguistique et technique.\r\n\r\n·        Fondamentaux de l’analyse et de la synthèse.\r\n\r\n·        Autres compétences personnelles utiles.\r\n\r\n·        Bases en informatique.\r\n\r\nProcédure de sélection :\r\n\r\n·        Examen du dossier (critères de sélection : mentions obtenues, nombre d’années d’études, notes dans les matières principales, etc.).\r\n\r\n·        Entretien.\r\n\r\n·       Présentation d’un projet préliminaire de thèse.'),
(13, 'الشهادات المطلوبة:\r\n\r\n             الشهادات التي تناسب محاور التكوين\r\n\r\n2.4 متطلبات المهارات العلمية لولوج التكوين في سلك الدكتوراه:\r\n\r\n– ضبط الاساسيات في العلوم الانسانية والاجتماعية وخاصة في محاور التكوين؛\r\n\r\n3.4. معايير ومساطر الانتقاء:\r\n\r\nدراسة الملف:\r\n معايير الانتقاء: التخصص، مشروع الدكتوراه، عدد الميزات، نقط المواد الأساسية؛\r\n\r\nمقابلة: مقابلة شفوية'),
(14, 'Diplômes requis : Diplôme de Master (bac+5) délivré par la FSJES, l’ENCG, Diplôme d’expert-comptable et tout diplôme reconnu équivalent.\r\n\r\n Prérequis scientifiques et pédagogiques : avoir étudié les modules d’économie et management. En l’occurrence, pour ‘économie : la macroéconomie, la microéconomie, les finances publiques, l’économétrie, la statistique, les mathématiques, les politiques économiques, les problèmes sociaux et économiques. Pour le management : Audit, Contrôle de gestion, Entrepreneuriat, Finance et théorie financière, Fiscalité d’entreprise et gestion fiscale, Marketing, grh, management, entrepreneuriat et management des territoires.'),
(15, 'الشهادات المطلوبة:\r\n\r\n– شهادة الماستر\r\n\r\n– ديبلوم الدراسات العليا المعمقة،\r\n\r\n– ديبلوم الدراسات العليا،\r\n\r\n– وكل شهادة أخرى معترف بمعادلتها للشواهد والديبلومات السابقة\r\n\r\n– الشواهد والديبلومات الأجنبية المسلمة من الجامعات المعترف بها، بشرط معادلتها للشواهد والديبلومات المغربية السابقة الذكر.\r\n\r\nمتطلبات المهارات العلمية لولوج التكوين في سلك الدكتوراه:\r\n\r\n– معارف أساسية في القانون العام، والفروع القانونية الأخرى ذات الصلة.\r\n\r\n– أن يكون الطالب قد أجرى بحثا جامعيا للتخرج من مسلك التكوين الذي تابع فيه الدراسة بعد الإجازة. ويجب أن ترتبط هذه المسالك بالشواهد والديبلومات المقبولة للتسجيل في مسلك الدكتوراه داخل المركز.'),
(16, 'Master en droit privé ou diplôme équivalent\r\n\r\nMaster en économie ou gestion à condition de justifier une connaissance pratique du droit économique (après délibération spéciale et acceptation du conseil du CEDoc.) .\r\n\r\n \r\n\r\nPrérequis de compétences scientifiques d’accès à la formation doctorale\r\n\r\nMaîtrise des fondamentaux du droit en général et du droit privé en particulier\r\n\r\nMaîtrise des fondamentaux des méthodes de la recherche juridique.\r\n\r\nMaitrise au moins d’une langue étrangère'),
(17, '4 الشهادات المطلوبة:\r\n\r\n– الماستر في القانون العام والدراسات السياسية، الماستر في القانون الخاص، الماستر في الاقتصاد، الماستر في التدبير، أو ما يعادل هذه الشهادات.\r\n\r\nMaster ou diplôme équivalent. Filières : Sciences Juridiques, Politiques, Economiques et de Gestion.\r\n\r\nDiplôme des ENCG, ISCAE, FSJES,\r\n\r\nالمعارف العلمية والبيداغوجية اللازمة:\r\n\r\n– ترصيد المعارف العامة العلمية والبيداغوجية في المجالات القانونية والسياسية والاقتصادية، وعلم التدبير.\r\n\r\nAvoir étudié des modules se rattachant aux domaines des sciences Juridiques, Politiques Economique et de Gestion tout en ayant une première expérience en recherche (projet de fin d’études, rapport de stage professionnel ou mémoire de fin d’études).'),
(18, 'Diplômes requis : Diplôme des Ecoles Nationales de Commerce et de Gestion, Diplômes de master et de master en Economie et Gestion, DESA, DESS et DES en économie et gestion et tout diplôme équivalent.\r\n\r\n. Prérequis de compétences scientifiques d’accès à la formation doctorale Avoir une première expérience en recherche (PFE ou mémoire de fin d’études) et avoir des connaissances satisfaisantes dans les matières fondamentales en économie et gestion.\r\n\r\n-Pour les titulaires du diplôme des ENCG, du Master ou Master spécialisé en Economie et Gestion ou de diplômes équivalents, les conditions de sélection sont les suivantes : avoir au moins trois mentions assez bien, ou supérieur durant les semestres 7, 8, 9 et 10 et avoir présenté un projet de recherche doctorale en relation avec le management des organisations.\r\n\r\n-Pour les titulaires d’un DESA, d’un DESS ou d’un DES en Economie et Gestion, les conditions de sélection sont les suivantes : avoir au moins une moyenne égale à 11,5 dans le diplôme et avoir présenté un projet de recherche en relation avec le management des organisations.\r\n\r\n \r\n\r\nEntretien :\r\nUn entretien oral devant des commissions composées des membres des structures de recherche des laboratoires est prévu pour les candidats ayant réussi l’examen écrit organisé le cas échéant.\r\n\r\n \r\n\r\nExamen écrit\r\nLes instances de la formation doctorale peuvent éventuellement décider de prévoir un examen écrit comme partie du processus de sélections, ces instances décideront des modalités de cet examen d’une manière Adhoc.'),
(19, 'الشهادات المطلوبة:\r\n\r\nشهادة الماستر في الشريعة أو الدراسات الإسلاميةأو الماستر من اصول الدين أو ماستر من كلية اللغة العربية أوالقانون الخاص أو القانون العام، أو شهادة الماستر من دار الحديث الحسنية أو ما يعادل هذه الشهادات.\r\n\r\nالمعارف العلمية والبيداغوجية اللازمة:\r\n\r\nالمعرفة العامة بالعلوم الشرعية والقانونية وما يرتبط بهما، والتمكن من الأدوات المعرفية للبحث.');
