INSERT INTO `formations_doctorales` (`id`, `intitule`, `description`, `contact_email`, `date_debut`, `date_fin`) VALUES
(1, 'Sciences et Génie de la Matière, de la Terre et de la Vie', 'La formation Doctorale a pour ambition de favoriser le développement de la recherche et de la formation pluridisciplinaire. Elle est adossée à 6 laboratoires de recherche,\r\n tous accréditées par notre Université. L’encadrement est assuré par plus de 133 enseignants chercheurs et ingénieurs permanents appartenant aux différentes structures de recherche et qui ont fait leur preuve, par la qualité de leur\r\n production scientifique et des projets et programmes de recherche qu’ils mènent. Les différentes structures engagées ont géré des unités de formation et de recherche (UFR) au niveau du DESA,\r\n DESS et Doctorat et gèrent actuellement des Masters Sciences et Techniques et des filières d’ingénieurs \r\n d’état. Elles dirigent des travaux de recherche dans différentes thématiques au sein de cette formation.\r\n  Les expériences acquises durant ce processus seront très profitables pour la gestion et la mise en place de cette \r\n  formation doctorale. La formation Doctorale proposée souhaite conforter les thématiques de recherche d’excellence et renforcer \r\n  celles qui sont en émergence ou qui nécessitent une restructuration ou mutualisation pour retrouver leur place dans la compétition \r\n  nationale ou internationale. Elle se fixe également les objectifs de développer les disciplines d’interface (sciences du vivant, chimie, sciences de la terre, matériaux, etc.) et de mettre en place\r\n   les grands programmes transversaux (environnement, du gène au médicament, etc.). Les thématiques de recherche qui seront développées, sont parmi les axes prioritaires de recherche définis par l’Université Sidi Mohamed Ben Abdellah et par \r\n   notre ministère de tutelle. Le choix des thématiques se trouve en parfaite harmonie avec les attentes de la région Fès Meknès. Plusieurs secteurs et activités de cet important pôle socio-économique seront concernés, de manière directe, à travers les résultats de \r\n   recherche et recherche développement des futurs docteurs.', 'vdr.fstf@usmba.ac.ma', '2021-01-01', NULL),
(2, 'Sciences de l’Ingénieur, Sciences Physiques, Mathématiques et Informatique', 'La formation Doctorale a pour ambition de favoriser le développement de la recherche et de la formation pluridisciplinaire. Elle est adossée à 6 laboratoires de recherche, tous accréditées par notre Université. L’encadrement est assuré par plus de 130 enseignants chercheurs et ingénieurs permanents appartenant aux différentes structures de recherche et qui ont fait leur preuve, par la qualité de leur production scientifique et des projet et programmes de recherche qu’ils mènent.\r\nLes différentes structures engagées ont géré des unités de formation et de recherche (UFR) au niveau du DESA, DESS et Doctorat et gèrent actuellement des Masters Sciences et Techniques et des filières d’Ingénieurs d’état. Elles dirigent des travaux de recherche dans différentes thématiques au sein de cette formation.\r\nLes expériences acquises durant ce processus seront très profitables pour la gestion et l’amélioration de cette formation doctorale.\r\nLa formation doctorale recouvre les disciplines scientifiques dans le domaine des mathématiques, de l’informatique, télécommunications, de la transmission et traitement d’Information, de l’automatique, de l’électronique, du génie électrique, du génie mécanique, du génie industriel, et de la physique des matériaux.\r\nLes thématiques de recherche qui seront développées, sont parmi les axes prioritaires de recherche définis par l’Université Sidi Mohamed Ben Abdellah et par notre ministère de tutelle.\r\nLe choix des thématiques se trouve également en parfaite harmonie avec les attentes de la région Fès-Meknès. Plusieurs secteurs et activités de cet important pôle socio-économique seront concernés, de manière directe, à travers les résultats de recherche et recherche/développement des futurs docteurs.', 'vdr.fstf@usmba.ac.ma', '2021-01-01', NULL),
(3, 'Sciences Médicales, Pharmaceutiques et Recherche Translationnelles', 'La formation doctorale vise le développement de la recherche médicale et la mise en place de la médecine translationnelle dans l’objectif d’améliorer la qualité de vie de nos malades en tenant compte des spécificités régionales et nationales. Elle est adossée à 5 laboratoires de recherche, dont quatre sont accrédités par notre Université et le 5ème est en cours d’accréditation. L’encadrement sera assuré par 269 enseignants chercheurs et cliniciens appartenant aux différentes structures de recherche et qui ont fait leur preuve, par la qualité de leurs productions scientifiques et des projets et programmes de recherche qu’ils mènent.\r\n\r\nLa particularité de la Faculté de Médecine réside dans la pluridisciplinarité des équipes de recherche. En effet chaque équipe de recherche associe au moins un enseignant chercheur clinicien. Ceci facilite les échanges entre fondamentalistes et cliniciens et favorise le développement de la recherche translationnelle. Aussi, cette recherche qu’on pourra décrire « du malade au malade » est accessible par un fort potentiel de recrutement des patients au niveau du centre hospitalo-universitaire Hassan II. Ce centre, auquel appartient aussi les enseignants de la Faculté de Médecine, est une structure d’enseignement et de soins tertiaires ce qui est très profitable pour la gestion et la mise en place de cette formation doctorale.\r\n\r\nLa formation doctorale proposée souhaite conforter pour les années d’accréditation les thématiques de recherche d’excellence et qui présentent des retombées indirectes et surtout directes sur la santé et la population. Ceci est supporté par la présence de nos deux principaux partenaires CHU Hassan II, et l’Institut de recherche sur le Cancer.', 'vicedoyenrecherche.fmpf@usmba.ac.ma', '2021-01-01', NULL),
(4, 'Sciences de l’Ingénieur, Technologies et Culture Industrielle (SITCI)', 'Sans aucun doute et plus que jamais l’économie mondiale est animée par la technologie, l’innovation et la recherche. Dans ce contexte, les compétences des docteurs sont reconnues comme un des facteurs stratégiques pour le développement économique et culturel des pays et leur nombre croissant en est d’autant plus souhaitable.\r\nNéanmoins, dans cette conjoncture concurrentielle accrue, face à la complexification des métiers et des carrières, la capacité d’adaptation des doctorants sera une condition majeure de leur réussite professionnelle.\r\nLa formation doctorale “Sciences de l’ingénieur, Technologies et Culture Industrielle” (SITCI) de l’Ecole Nationale des Sciences Appliquées de Fès a pour but de faire acquérir aux doctorants des compétences utiles à leur travail de jeune chercheur et à leur poursuite de carrière, dans le secteur académique comme en-dehors.\r\nCette formation doctorale tente à répondre à des enjeux sociétaux majeurs tels que : la transformation numérique et l’intelligence artificielle, la transition énergétique, les nouveaux matériaux pour des applications médicales et environnementales, les secteurs de l’aéronautique, de l’automobile, de l’agro-alimentaire et de la pharmacie.\r\nPour que ses docteurs aient accès à un maximum d’opportunités professionnelles, des dispositifs d’accompagnement et de formations complémentaires sont proposés par la SITCI afin de renforcer les aptitudes acquises dans le cadre du travail même de recherche (la thèse).\r\nDans le cadre de cette formation doctorale SITCI, les doctorants seront préparés à la démarche de recherche d’emploi en les conduisant à identifier les compétences multiples mises en œuvre au cours des années de thèse et à les valoriser dans des situations professionnelles diversifiées. A cet égard, SITCI vise à :\r\n1. accroître les connaissances ;\r\n2. partager la culture scientifique, technique et industrielle ;\r\n3. valoriser les résultats de la recherche au service de la société. A cet effet, elle s’attache au développement de l’innovation, du transfert de technologie lorsque celui-ci est possible, de la capacité d’expertise et d’appui aux associations et fondations, reconnues d’utilité publique, et aux politiques publiques menées pour répondre aux défis sociétaux, aux besoins sociaux, économiques et du développement durable ;\r\n4. promouvoir la culture scientifique, technique et industrielle.\r\n\r\nLa formation Doctorale SITCI a pour ambition de favoriser le développement de la recherche et de la formation pluridisciplinaire. Elle est adossée à 4 laboratoires de recherche, tous accréditées par notre Université :\r\n1. Laboratoire d’Ingénierie, Systèmes et Applications – ENSA de Fès\r\n2. Laboratoire Intelligence Artificielle & Sciences des données & Systèmes Émergents – ENSA de Fès\r\n3. Laboratoire des Technologies Innovantes – EST de Fès\r\n4. Laboratoire des Technologies et Services Industriels – EST de Fès\r\nL’encadrement sera assuré par 103 enseignants-chercheurs permanents appartenant aux différentes structures de recherche et qui ont fait leur preuve, par la qualité de leur production scientifique et des projet et programmes de recherche qu’ils mènent.\r\nSoulignons que les expériences acquises dans ces différentes structures seront très profitables pour la gestion et la mise en place de cette formation doctorale.\r\nLa formation doctorale SITCI proposée souhaite conforter pour les années 2022 – 2026 les thématiques de recherche d’excellence et renforcer celles qui sont en émergence ou qui nécessitent une restructuration ou mutualisation pour retrouver leur place dans la compétition nationale ou internationale.\r\nLes thématiques de recherche qui seront développées, sont parmi les axes prioritaires de recherche définis par l’Université Sidi Mohamed Ben Abdellah et par notre ministère de tutelle.\r\nLa formation doctorale SITCI recouvre les disciplines scientifiques dans le domaine de l’Automatique, la Robotique, le Biomédical, la Pharma, la Construction et travaux publics, l’Électronique et la Photonique, les Énergies, l’Environnement et la Sécurité, le Génie industriel, l’Ingénierie des transports, l’Innovation, les Matériaux, la Mécanique, les Mesures et les Analyses, les Procédés chimie – bio – agro, les Sciences fondamentales, les Technologies de l’information, le Génie civil, le Génie urbain et l’Informatique\r\nLa formation doctorale SITCI touchera les secteurs industriels divers tels que l’Aérospatial, l’Agroalimentaire, l’Automobile, les Éco-industries, les Équipements industriels, Plasturgie et Nouveaux procédés de fabrication.\r\nLe choix des thématiques se trouve également en parfaite harmonie avec les attentes de la région Fès Meknès. Plusieurs secteurs et activités de cet important pôle soci-économique seront concernés, de manière directe, à travers les résultats de recherche et recherche développement des futurs docteurs.', 'd_adj.ensaf@usmba.ac.ma', '2021-01-01', NULL),
(5, 'Sciences, Sciences de l’Ingénieur et Métiers d’Enseignement', 'Cette formation doctorale vise à contribuer au développement de la recherche scientifique dans des domaines variés des sciences, des sciences et techniques de l’ingénieur ainsi qu’aux métiers d’enseignement. Elle ouvre ainsi une opportunité pour les jeunes chercheurs désireux de poursuivre des recherches auprès d’une équipe expérimentée qui a fait ses preuves dans les domaines de recherches proposés et ce par la quantité et la qualité de sa production et les différents projets auxquels elle a contribué.\r\nCette formation se voit généraliste et va dans le même sens que la vocation de notre établissement et celle des autres enseignants. Comme c’est déjà mentionné elle propose un domaine de recherche en sciences qui englobe les mathématiques, l’informatique, la physique, la chimie, les sciences de la vie et de la terre. Cette recherche vise à développer une recherche théorique ou expérimentale qui va tenter de résoudre certains problèmes soulevés par les différents chercheurs.\r\nLe domaine des sciences de l’ingénieur va s’ouvrir sur le monde de la créativité pour poursuivre le développement technologique que connait le monde aujourd’hui telle que l’intelligence artificielle, les systèmes embarqués, le génie informatique etc…\r\nLe domaine des métiers d’enseignement va s’occuper à développer des technologies éducatives, des méthodes didactiques et pédagogiques pour préparer l’enseignement futur et améliorer le système éducatif.\r\n\r\nCes domaines de recherche sont en parfaite harmonie avec les attentes de notre université, de notre région et de notre pays.', 'saad.bennanidosse@usmba.ac.ma', '2021-01-01', NULL),
(6, 'Sciences et Techniques et Innovation', 'La formation Doctorale a pour ambition de favoriser le développement de la recherche et de la formation pluridisciplinaire dans les domaines des sciences et techniques. Elle est adossée à deux laboratoires de recherche, tous accréditées par notre Université. L’encadrement sera assuré par des enseignants chercheurs permanents appartenant aux différentes structures de recherche et qui ont fait leur preuve, par la qualité de la formation qu’ils dispensent dans les filières de licence et de masters accréditées, de leur production scientifique et des projets et programmes de recherche qu’ils mènent.\r\n\r\nLes expériences acquises durant ce processus seront très profitables pour la gestion et la mise en place de cette formation doctorale.\r\n\r\nLa formation Doctorale proposée souhaite conforter pour les années 2021 – 2026 les thématiques de recherche d’excellence.\r\nLa formation doctorale recouvre les disciplines scientifiques dans le domaine de la physique des mathématiques, de l’informatique, de la biologie, de la géologie et de la chimie.\r\n\r\nLes thématiques de recherche qui seront développées, sont parmi les axes prioritaires de recherche définis par l’Université Sidi Mohamed Ben Abdellah et par notre ministère de tutelle et qui répondent aux besoins de développement local, régional et national.\r\n\r\nPlusieurs secteurs et activités d’importance socio-économique seront concernés, de manière directe, à travers les résultats de recherche et recherche développement des futurs docteurs', 'jaouad.bouarfa@usmba.ac.ma', '2021-01-01', NULL),
(7, 'Sciences de l’éducation, Psychologie, Langues, Sciences sociales, Philosophie, et Sciences Islamiques', 'La formation Doctorale a pour ambition de favoriser le développement de la recherche et de la formation pluridisciplinaire. Elle est adossée au Laboratoire des Sciences Humaines Appliquées, accrédité par notre Université.\r\n  L’encadrement sera assuré par les enseignants chercheurs permanents appartenant à trois établissements universitaires : Ecole Normale Supérieure, Faculté des Lettres-Sais et Faculté des Lettres et Sciences Humaines-Dhar el Mahraz.\r\n\r\nLes enseignants chercheurs, membres permanents de notre Laboratoire, ont géré et gèrent encore des filières et des recherches à différents niveaux de formation universitaire. A titre d’exemple nous citerons les filières et les axes de recherche suivants :\r\n\r\n-Fondements de l’éducation et de l’apprentissage\r\n\r\n-Psychologie et Apprentissage\r\n\r\n-Education spécialisée\r\n\r\n-Enseignement du français au secondaire\r\n\r\n-Enseignement primaire\r\n\r\n-Enseignement de l’histoire-géographie\r\n\r\n-Enseignement de la langue Amazighe\r\n\r\n-Assistance sociale\r\n\r\n–            …..\r\n\r\n \r\n\r\nLes expériences acquises durant ce processus seront très profitables pour la gestion et la mise en place de cette formation doctorale.\r\n\r\nLa formation Doctorale proposée s’étalera sur les années 2021 – 2027. Ainsi, seront proposées des thématiques de recherche innovantes et qui émanent des besoins réels de notre société, et ce en adéquation avec la spécificité de notre Laboratoire initiant la recherche appliquée en sciences humaines dans notre pays.\r\n\r\nLa formation doctorale recouvre les disciplines scientifiques dans le domaine des Sciences de l’Education, la Psychologie, les Langues, la Communication, le Théâtre et les arts dramatiques, la Géographie, les sciences islamiques, les Didactiques des Disciplines (philosophie, histoire géographes, langues, éducation islamique…) et le Management des établissements d’enseignement et de formation.\r\n\r\nLe choix des thématiques se trouve également en parfaite harmonie avec les attentes de la région Fès Meknès. Plusieurs secteurs et activités seront concernés, de manière directe ou indirecte, à travers les résultats de recherche et recherche action des futurs docteurs.', 'saad.bennanidosse@usmba.ac.ma', '2021-01-01', NULL),
(8, 'Mécanismes de pensés et Dynamiques Humaines et territoriales', 'د1.1. تسمية التكوين في سلك الدكتوراه:\r\n“آليات التفكير والديناميات الإنسانية والمجالية”\r\n\r\nد2.1. وصف مقتضب:\r\nيعتبر البحث في آليات التفكير والديناميات الإنسانية والترابية والتراثية من أنواع البحوث الجديدة التي تستأثر باهتمام الباحثين والدارسين في مجالي الفلسفة والعلوم الإنسانية والاجتماعية راهنا ويرجع ذلك بالأساس إلى الوعي بضرورة بناء وبلورة مقاربة متعددة التخصصات (فلسفية، منطقية، سيكولوجية، سوسيولوجية، دينية، مجالية تاريخية وتراثية ) هدفها الكشف عن كيفية اشتغال ميكانيزمات التفكير من جهة أولى وعما يحرك ويغذي التحولات الاجتماعية والنفسية والإنسانية بصفة عامة وعوامل التطور عموما من جهة ثانية. حيث إن هناك جدلية بين آليات التفكير والديناميات الإنسانية والمجالية. فالأولى تؤطر مختلف التحولات الاجتماعية والإنسانية وتحللها وتفهمها وتفسرها وتبين اتجاهاتها وإيقاعاتها ودلالاتها إلى حد أن هذه الأخيرة –أي التحولات الاجتماعية والإنسانية والمجالية – لا تعدو أن تكون ثمرة ما ينتجه الفكر البشري في الميادين الفكرية والاجتماعية والنفسية والمجالية. مقابل ذلك نجد أن التحولات الاجتماعية والإنسانية بمثابة المواد الخام التي يتم بلورتها بفضل آليات الاشتغال الذهني والمجهودات النظرية والمنهجية المبذولة من طرف الباحثين والدارسين في المجال. لقد أصبح التكامل بين مختلف الحقول المعرفية (الفلسفة، علم الاجتماع، علم النفس، التاريخ، الجغرافية، الدراسات الإسلامية، اللغات…) وتبادل الآراء والتجارب والخبرات بين الباحثين مطلبا ضروريا وملحا في نفس الوقت نظرا لما تفرضه المرحلة الراهنة من تعقيد وتداخل وتشابك القضايا والإشكاليات بالدرجة الأولى ومقومات البحث والعمل الأكاديمي والجامعي عامة وتأطير وتكوين الموارد البشرية خاصة بالدرجة الثانية. فالفعالية البشرية تقتضي التكوين الجيد والفعال. وهذا الأخير يستدعي بدوره الانطلاق من فلسفة تربوية دينامية مندمجة وشمولية والتكيف مع الواقع الذي يتغير باستمرار. وذلك من أجل مواكبة كل جديد على مستوى المعارف (النظريات والمناهج) وتوظيفها في خدمة التنمية البشرية المنشودة. فلا تقدم ولا نهضة بدون سياسة للمعرفة.\r\nكما يحرص التكوين على تلقين الطالب-الباحث مبادئ ومناهج البحث العلمي وما يتطلبه ذلك من موضوعية وحيادية وعمق في تحليل الظواهر الإنسانية بمختلف تجلياتها. هذا في أفق المساهمة في إشعاع الجامعة وتفوقها في المجال الأكاديمي والعلمي في ظل المنافسة العالمية في هذه الميادين المعرفية. وتحقيق ما يصبو إليه بلدنا من رقي حتى يكون في مصاف الدول الرائدة.\r\nوأخيرا، يسعى هذا التكوين إلى مد الجسور بين مجمل هذه التخصصات المهتمة ب”أليات التفكير والديناميات الإنسانية والمجالية” عبر تطوير البحث العلمي والأكاديمي الرصين في مختلف أبعاد الظاهرة الإنسانية بامتداداتها التاريخية، التراثية، المجالية والترابية وانعكاساتها على المحيط السوسيواقتصادي تنمويا وتواصليا بما يفتح آفاق العمل وتشبيك العلاقات الخادمة للاقتصاد المعرفة.\r\n\r\nد3.1. الأهداف:\r\n– تكوين الطلبة بواسطة البحث ومن أجل البحث وذلك بتأطيرهم داخل بنيات البحث المستقبلة التي يستند عليها هذا التكوين؛\r\n– تمكين الطلبة الباحثين من اكتساب منهجية البحث الأكاديمي؛\r\n– توجيه الطلبة لإنجاز أبحاثهم النظرية والميدانية في مواضيع تساهم في تقدم البحث\r\nالعلمي الجامعي والتنمية الثقافية والسوسيو اقتصادية؛\r\n– توجيه الطلبة للبحث في ميادين أكثر ملائمة مع متطلبات المحيط السوسيواقتصادي والثقافي.\r\n\r\nد4.1. الانعكاسات العلمية:\r\no تحسين مستوى التكوين لدى الطلبة نظريا ومنهجيا وتطبيقيا؛\r\no تأهيل الطلبة للاندماج في مجال مجتمع المعرفة والبحث العلمي؛\r\no تكوين طلبة باحثين يتمتعون بالكفاءة التي تؤهلهم للاندماج في سلك التعليم العالي والجامعي وغيره من المؤسسات العمومية والخاصة والمساهمة في تطوير البحث العلمي؛\r\no تطوير المهارات البحثية والناعمة (Soft Skills)؛\r\no تكوين وتوجيه الطلبة في مجال صياغة المشروع المهني والعلمي.\r\n\r\nد5.1. الانعكاسات البيداغوجية:\r\no الرفع من قدرات الطلبة ومؤهلاتهم المعرفية؛\r\no تدبير مشروع الدكتوراه ليتم إنجازه في أحسن الظروف؛\r\no جعل العلاقة بين الأستاذ والطالب أكثر استمرارية ومردودية؛\r\no خلق علاقات التبادل الإيجابي بين الطالب والأستاذ وذلك من خلال تفعيل دور بنيات البحث المتوفرة داخل المؤسسة الجامعية؛\r\no إعداد متخصصين في مجالات التكوين أعلاه ذوي خبرة وكفاءة؛\r\no تكوين الطلبة الباحثين في مجال أخلاقيات البحث العلمي النزيه.\r\n\r\nد6.1. الانعكاسات الاقتصادية والاجتماعية والثقافية المتوقعة:\r\n(التركيز على أهمية المشروع في التنمية الجهوية والوطنية والتشغيل)\r\no تكوين أطر كفأة قادرة على التكيف مع متطلبات المحيط السوسيواقتصادي والثقافي؛\r\no إتاحة الفرص للطلبة المتفوقين لاستكمال تكوينهم في المجالات التي تشكو من نقص في الموارد البشرية في مجال العلوم الإنسانية والاجتماعية؛\r\no خلق دينامية ثقافية وعلمية في الجامعة والمدينة من خلال الأنشطة الثقافية والعلمية التي يساهم فيها الأساتذة والطلبة المنتمون لبنيات البحث النشطة والمتدخلة في تكوينات الدكتوراه؛\r\no تخريج أطر مؤهلة لتطوير التواصل الروحي والثقافي للمغرب في انفتاحه على إفريقيا وضفتي المتوسط بشكل خاص وعلى باقي بقاع العالم؛\r\nالمساهمة في إحداث علاقات شراكة وتعاون مع جامعات أجنبية', 'Boucheta.elkhazzanan@usmba.ac.ma', '2021-01-01', NULL),
(9, 'Langues, Littérature et Formes Symboliques et culturelles', 'D1. 1. Intitulé de la formation doctorale :\r\nLangues, Littératures, formes symboliques et culturelles\r\nاللغات والآداب والأشكال الرمزية والثقافية\r\nD1. 2. Description sommaire :\r\nCette formation doctorale : Langues, Littératures, formes symboliques et culturelles a pour vocation première d’assurer aux doctorants une formation de qualité à la recherche et par la recherche, dans le domaine des études linguistiques, littéraires, artistiques et culturelles et de leur investissement pédagogique et didactique. Parallèlement, à cela, des formations complémentaires transversales et spécifiques sont programmées annuellement pour faciliter l’intégration du doctorant dans la communauté des chercheurs afin de favoriser son insertion professionnelle.\r\nCette formation, dont la discipline dominante est orientée vers « les approches scientifiques du langage, les arts, les littératures et/ou la didactique, la communication  »,est fondée à la fois sur le grand potentiel de recherche et d’encadrement qu’offrent les différente laboratoires auxquels elle est adossée et qui développent des recherches dans le domaine des langues, des lettres, des sciences cognitives, des cultures et de la didactique des disciplines, sur les filières de Master accréditées dans notre établissement et qui constituent son vivier principal.\r\nA l’issue de la formation, il sera délivré un diplôme de Doctorat en\r\n “Langues, Littératures, formes symboliques et culturelles”\r\ndans l’une des spécialités suivantes:\r\n-Sciences du langage\r\n– Sciences du langage cognition\r\n– Didactique etIngénierie de Formation\r\n– Didactique et éducation\r\n– Langue et communication\r\n– Littératures et Histoire de l’art\r\n– Littératures et Critique d’art\r\n– Langue et Littérature françaises\r\n– Langue et Littérature anglaises\r\n– Langue et Littérature espagnoles\r\n– Langues et littérature allemandes\r\n– Langues et littérature russes\r\n– Langues et littérature arabes اللغة العربية وآدابها\r\n– النحو/ اللسانيات/ أدب قديم/ أدب حديث/ أدب مغربي/ أدب أندلسي\r\nStructures de recherche d’accueil des doctorants :\r\n–  Laboratoire des Sciences du Langage, Littératures, Arts, Communication &Histoire (SLLACH)\r\n–  Laboratoire de recherche en Cultures, Représentations, Éducation, Didactique & Ingénierie de Formation (CREDIF)\r\n–  Psychological, Sociological and Cultural Studies (PSCS)\r\n–  Dialogiques- Equipe Interdisciplinaire sur la Recherche sur l’Art, lesLittératures l’Esthétique, le Discours et les Cultures (EIRALEDIC)\r\n–  مختبر الأبحاث المصطلحية والدراسات النصية(RTET)\r\nFilières de MASTER\r\n-Sciences du langage : Théories linguistiques et description langagières.\r\n-Gender studies\r\n-Cultural studies : Cultures, Idendities and Nationhood in Morocco\r\n-Language, Communication and Society\r\n-Applied Language Studies and Reaserch in Higher Education\r\n-Translation and Cross-Cultural communication\r\n-تحالف الحضارات و حوار الأديان\r\nD1. 3. Objectifs :\r\n-Renforcer les compétences acquises dans le cadre du master en matière de culture,littérature,linguistique, sciences cognitives, didactique et pédagogie universitaire, recherche documentaire, méthodologie et manipulation des nouvelles technologies d’information et de communication ;\r\n-former les étudiants à la recherche et par la recherche en les faisant participer aux activités desstructures d’accueil ;\r\n-développer les compétences des étudiants en matière de savoir et de savoir-faire, en vue defaciliter leur insertion professionnelle ;\r\n-impulser la recherche éducative et didactique en rapport avec le contexte marocain ;\r\n-investir le savoir théorique dans l’exploration et l’analyse de corpus (littéraires, langagiers, culturels …) ;\r\n-Mobiliser les savoirs produits par les différentes sciences humaines (telles que les sciences dulangage, la sémiotique, l’analyse de discours, la linguistique appliquée, la didactique des languesetdes disciplines, les sciences de l’éducation, l’ingénierie de formation ainsi que les étudesculturelles, interculturelles, artistiques, littéraires) dans l’analyse des lieux, des modes et desprocessus deproduction et de médiation sociale des systèmes culturels ( école, centres deformation, systèmeséducatifs, contenus, savoirs, dispositifs didactiques et pédagogiques,compétences…) ;\r\n-Analyser, comprendre les créations artistiques, mettre en œuvre et interroger toutes les approches(disciplinaires, interdisciplinaires et méthodologiques) constitutives de l’histoire de l’art et de lacritique d’art ;\r\n-Contribuer à l’écriture de l’histoire de l’art au Maroc en essayant d’interroger les fondements, lanature les spécificités de la production artistique au Maroc ;\r\n-Maîtriserles techniques de composition et d’interprétation des discours sur l’art ;\r\n-Former à la recherche littéraire dans une perspective et à partir d’une approche comparatistes ;\r\n-Analyser des formes d’expression ; comparer et critiquer des littératures et des arts, des courants,des œuvres ;\r\n-Identifier, décrire et étudier les modalités de la création littéraire et de sa réception ;\r\n-Etudier la littérature de voyage dans ses divers aspects : documentaire, esthétique et idéologique ;\r\n-Étudier les mutations contemporaines affectant les constructions subjectives et identitaires, ainsique les liens sociaux, dans le champ des institutions socio-éducatives ;\r\n-Analyser les processus de production des inégalités dans le milieu scolaire (sociales, sexuées et territoriales) en matière de scolarisation et d’accès aux savoirs, aux modes de travail intellectuel et aux pratiques culturelles ;\r\n-Questionner, à travers des éclairages théoriques et conceptuels différents et des approchesméthodologiques diversifiées, le fait littéraire dans tous ses aspects, dimensions etmanifestations ;\r\n-Initier des projets de recherche portant sur la didactique des langues-cultures en focalisant l’intérêtsur les différents enjeux de l’enseignement/apprentissage des langues en contexte plurilingue etmulticulturel ;\r\n-Promouvoir la recherche sur les gestes professionnels des enseignants et leur impact surl’appropriation et l’acquisition des savoirs ainsi que le développement des compétences desapprenants ;\r\n-Produire des connaissances et entreprendre des études rigoureuses, documentées et étayéesscientifiquement sur les politiques, les processus et les systèmes éducatifs en contexte marocain ;\r\n-Mener des études comparatives des processus d’enseignement/apprentissage dans des contextesdivers et des milieux socio-économiques différents ;\r\n-Conduire des recherches visant à expérimenter des dispositifs ou des interventions dans desclasses et des établissements ;\r\n-Conduire des recherches visant à l’accompagnement d’équipes professionnelles ou à l’analyse depratiques d’enseignement et de formation engagées sur des terrains divers ;\r\n-Etudier les rapports sociaux entre les sexes, tout en s’interrogeant sur les processus dereproduction des normes genrées dans les différentes organisations et institutions sociales (écoles,administrations, entreprises…) ;\r\n-Mener des recherches interdisciplinaires concernant l’impact des médias et des réseaux sociauxsur les représentations relatives à l’institution scolaire et à son rôle dans la formation des jeunes ;\r\n-Initier des projets de recherche portant sur des problématiques relatives à la formation et àl’insertion des jeunes dans le contexte marocain.\r\n-قراءة منتوجنا اللغوي والأدبي التراثي القراءة العلمية الدقيقة الفاحصة والمعتمدة على النظر الموضوعي.\r\n-الانفتاح على معضلات النص الأدبي ونقده مصطلحا وقراءة وتأويلا وتحقيقا.\r\n-اكتساب النظريات المعاصرة ومناهج التحليل الحديثة في اللسانيات والأدب.\r\n-بلورة تصور علمي لتنمية البحث العلمي وجعل مشاريع الدكتوراه في اللغة والأدب منفتحة على قضايا المجتمع.\r\n-تكوين فكر نقدي وعلمي للمنتسبين إلى تكوين الدكتوراه، ودعم روح الابتكار في مجالات التخصص.\r\n-تطوير معارف ومدارك الطلبة الباحثين التي اكتسبوها في سنوات الإجازة والماستر.\r\nD1. 4. Retombées scientifiques :\r\n-Renforcer les synergies entre les différentes structures impliquées dans la formation doctorale enexploitant les transversalités qui existent entre elles dans le cadre de séminaires, conférences,colloques, journées d’études, etc.\r\n-Etablir des interrelations entre les recherches disciplinaires et les recherches en didactique.\r\n-Promouvoir la recherche disciplinaire en rapport avec le contexte immédiat tant au niveau del’objet de la recherche que de son exploitation sur le plan socio-culturel et éducatif.\r\n-Enrichir le fonds documentaire par le recueil de données propres au champ culturel national.\r\n-Inciter les étudiants-chercheurs à s’impliquer activement dans la recherche scientifique, par l’organisation d’ateliers, de journées de présentation des thèses déjà soutenues, la présentation des recherches en cours.\r\n-Accompagner les doctorants dans la rédaction d’articles scientifiques et favoriser leur publication.\r\n-تكوين الطلبة الباحثين من أجل امتلاك تصور علمي دقيق للمصطلحات والمفاهيم في شتى المعارف والعلوم العربية\r\n-تمكين الطلبة الباحثين من إدراك المناهج اللسانية واستثمارها في الأنساق المجاورة.\r\n-استثمار اللسانيات واللسانيات التطبيقية في قضايا اللغة العربية وتهيئتها.\r\n-تمكين الطلبة الباحثين من فهم التراث النقدي والأدبي وتحليل نصوصه.\r\n-إرشاد الطلبة الباحثين إلى أماكن التراث المخطوط وخصائصه، وتشجيعهم على الإقبال على صنعة التحقيق.\r\n-تعريف الطلبة الباحثين برصيد بلدنا من التراث المخطوط في علوم العربية، والاستفادة منه علميا وسياحيا.\r\n-تمكين الطلبة الباحثين من الإلمام بمختلف المناهج التي تعنى بالشعر، والمسرح، والسرد، والصورة، وبالعلاقة بينها.\r\n-تنمية وصقل مهارات الطلبة الباحثين بالكشف عن المواهب، وتلقينهم تقنيات الكتابة الإبداعية.\r\n-تمكين الطلبة الباحثين من مهارات المقاربة المعرفية والمنهجية والفنية للأدب المغربي والأندلسي.\r\nD1. 5. Retombées pédagogiques :\r\n-Accompagner l’étudiant-doctorant dans la définition de son sujet, de son objet de recherche et del’approche appropriée pour le traiter ;\r\n-Faire réfléchir les étudiants sur les méthodes d’enseignement et la didactique des disciplines en application dans le champ éducatif marocain ;\r\n-Offrir la possibilité de mieux connaître et traiter les troubles du langage dans l’enseignement et l’éducation ;\r\n-Faire acquérir un savoir pédagogique et didactique dans le domaine des études culturelles et de L’enseignement/apprentissage des langues ;\r\n-Contribuer à pallier la pénurie de candidats qualifiés pour les postes de professeurs de l’enseignement supérieur assistants à l’université par la formation d’enseignants chercheurs capables de s’adapter aux exigences du système modulaire au sein de filières d’enseignement ;\r\n-التأهيلللمهنالتدريسية والتربوية؛\r\n-التأهيل للعمل في مجالات النشر والتحقيق وخدمة المخطوط؛\r\n-التأهيل للعمل في المكتبات والأرشفة والفهرسة؛\r\n-التخصص في اللسانيات وفي التخطيط اللساني؛\r\n-مهنة الترجمة ومهن التدقيق والمراجعة لغوي في اللغة العربية؛\r\n-مهن التنشيط الثقافي والإعلامي والكتابة الصحافية؛\r\nD1. 6. Retombées socio-économiques et culturelles pressenties :\r\n      (Mettre l’accent sur l’intérêt du projet pour le développement régional, national et pour l’emploi)\r\n-Orientation de la recherche vers les besoins d’ordre socio-économiques de la région ;\r\n-Contribution au développement des secteurs de l’édition électronique, de la documentationinformatisée et de la création artistique utilisant les technologies numériques ;\r\n-Encouragement et soutien des actions de coopération entre l’université et le monde industriel, notamment l’industrie du livre, l’ingénierie linguistique, la création de didacticiels ;\r\n-Mise en place, en étroite collaboration avec les responsables politiques, culturels et économiques de la région, d’une stratégie de développement humain fondé sur la mise en adéquation de la formation et du marché du travail ;\r\n-Participation au développement humain à travers l’amélioration de l’enseignement en général ;\r\n-Ouverture sur le monde socio-économique en favorisant le développement des politiques de création d’entreprises et de recrutement des lauréats de la formation doctorale ;\r\n-formation d’une élite de scientifiques qui auront pour tâche la promotion de la vie culturelle et sociale ;\r\n-تأهيل الطلبة الباحثين للانخراطفي منظومة التربية والتكوين وطنيا؛\r\n-الاستثمار العلمي والسياحي على المستوى الوطني والجهوي للرصيد التراثي المخطوط في علوم العربية؛\r\n-تأهيل التراث لاستثماره في مختلف مجالات التنمية (الترجمة، التعريب، معلوميات، صناعة المعاجم الإلكترونية والورقية…)؛\r\n-جعل التهيئة اللسانية والتخطيط للغة العربية ضمن برامج التربية والتعليم ودعم اللغة العربية في النسيج الاقتصادي والاجتماعي؛\r\n-استثمار مؤهلات الطلبة الباحثين في نشر المعرفة في الأوساط الجامعية وتفعيل الاهتمام باللغة العربية كلغة رسمية وطنية إلى جانب اللغات الرسمية الأخرى؛\r\n', 'Boucheta.elkhazzanan@usmba.ac.ma', '2021-01-01', NULL),
(10, 'Histoire, Patrimoine, et Sciences Religieuses et Sociales', 'La Formation doctorale “Histoire, Patrimoine, et Sciences Religieuses et Sociales” explore l’héritage historique, culturel et religieux du Maroc, en intégrant l’étude des patrimoines matériels et immatériels (architecture, manuscrits, traditions) et leur sauvegarde, ainsi que les dynamiques politiques et diplomatiques marocaines (médiévales à contemporaines). Il analyse les relations internationales, les structures tribales, les mouvements de résistance maghrébins, et les mutations socio-économiques modernes pour décrypter les enjeux locaux et globaux.\r\n\r\nLe volet sciences religieuses traite du droit islamique (Fiqh) appliqué aux défis actuels, des études coraniques, et des débats théologico-sociaux (pluralisme, genre, dialogue interreligieux). Les sciences sociales (sociologie du développement, éducation, travail) et la psychologie appliquée (clinique, troubles des apprentissages) complètent la formation pour étudier et interpréter les comportements humains et sociétaux.', 'samir.bouzouita@usmba.ac.ma', '2021-01-01', NULL),
(11, 'Langues, Littérature, Communication et Media', 'La formation doctorale : « Langue, Littérature, Communication et Media » s’inscrit dans le contexte général de l’évolution de la formation à et par la recherche et couvre les intérêts scientifiques des chercheurs et des doctorants affiliés à des structures accréditées.\r\n\r\nElle s’appuie sur les structures de recherche reconnues par l’université et organisée autour de thématiques pluridisciplinaires. Elle ambitionne de contribuer à l’innovation de la recherche scientifique. Elle soutient et prône l’ouverture sur des aires de recherche capables d’ancrer différents champs disciplinaires dans le contexte local en impulsant des thématiques plus directement au service de la formalisation de la culture nationale, avec tout ce que celle-ci articule comme valeurs d’ouverture et de dialogue, et tout ce qu’elle implique comme enjeux identitaires et civilisationnels.\r\n\r\nCette formation a été créée pour répondre au besoin de constituer un nouvel espace de formation, assurant un encadrement scientifique des doctorants-chercheurs aligné sur les nouvelles orientations de la recherche scientifique. Ce programme vise à :\r\n\r\nContribuer à enrichir la recherche scientifique sur les langues, les littératures et les sciences de l’information et de la communication au sein des facultés de Lettres et Sciences Humaines.\r\nFormer des cadres et des compétences spécialisés en littérature, linguistique, cultures, communication et médias, à travers un apprentissage académique rigoureux. Ces profils seront capables de mener des recherches dans des domaines liés à leurs formations et spécialités, ainsi que de défendre leurs projets de recherche.\r\nRenforcer l’intégration des chercheurs en formation doctorale au sein des instances scientifiques, et développer la coopération entre les différentes structures de recherche de l’institution œuvrant dans les domaines de la Littérature, de la Linguistique, et des Sciences de l’Information et de la Communication.', 'samir.bouzouita@usmba.ac.ma', '2021-01-01', NULL),
(12, 'Ressources, Aménagement et Développement Territorial', 'La formation doctorale “Ressources, Aménagement et Développement Territorial” vise à comprendre les composantes et les dynamiques des milieux et des ressources dans toutes leurs dimensions : naturelles, humaines, économiques, spatiales et environnementales, qu’il s’agisse de leur état passé (hérité), actuel ou de leurs évolutions possibles. L’objectif est d’en proposer une exploitation rationnelle en faveur d’un développement local durable et intégré, respectant les équilibres et les mutations territoriales.\r\n\r\nDans cette optique, le caractère global de la formation implique d’intégrer les divers enjeux scientifiques de la géographie selon une perspective épistémologique cohérente et interconnectée. Une compréhension approfondie des milieux, des ressources et de l’aménagement du territoire exige en effet des études multidisciplinaires, incluant notamment :\r\n\r\nLes fondements naturels et environnementaux des phénomènes étudiés ;\r\nLes facteurs humains, sociaux, comportementaux et leurs contextes ;\r\nLes conditions techniques, juridiques et les outils nécessaires à l’analyse et à la gestion des phénomènes ;\r\nLes études évolutives situant les phénomènes dans leur temporalité (passé, présent, futur) ;\r\nLes problématiques pratiques liées à l’aménagement et à la gestion des ressources.\r\nPar ailleurs, les acteurs de l’aménagement du territoire national font face à des défis croissants, notamment la constitution de bases de données géoréférencées et leur utilisation comme outils d’aide à la décision. Les collectivités locales, institutions publiques, bureaux d’études et entreprises privées ont un besoin urgent de cadres spécialisés dotés de compétences élevées en analyse et gestion de l’information géographique, ainsi qu’une maîtrise des enjeux de l’aménagement et du développement territorial.\r\n\r\nDans le cadre de la réforme universitaire aux niveaux Licence et Master, l’enseignement des *Systèmes d’Information Géographique (SIG)* a été intégré pour moderniser les approches pédagogiques. Ce domaine occupe ainsi une place centrale dans la formation doctorale, afin de renforcer la recherche appliquée grâce aux technologies de télédétection et de SIG, notamment dans l’aménagement aux échelles régionale et locale. Cette orientation répond aux besoins concrets de planification territoriale résiliente et innovante, alignée sur les défis socio-économiques et environnementaux contemporains.', 'samir.bouzouita@usmba.ac.ma', '2021-01-01', NULL),
(13, 'Espace, Histoire, Langues et Littérature', 'يندرج إعداد مشروع التكوين في الدكتوراه، في إطار تفعيل المواد 16، 49، 50 و51 من قانون الإطار 17- 51، المتعلقة بمنظومة التربية والتكوين والبحث العلمي والرؤية الاستراتيجية للإصلاح 2015 – 2030، من أجل مدرسة الإنصاف والجودة والارتقاء التي أعدها المجلس الأعلى للتربية والتكوين والبحث العلمي. ويستمد مشروعيته من مختبر ”المجال، التاريخ، الدينامية والتنمية المستدامة” ومختبر “اللغة والأدب والترجمة”. والذي يضم في عضويته أساتذة من مختلف التخصصات، ولكن في تكامل منهجي ومعرفي في التكوينات، وهي تجمع بين الآداب واللغات والتاريخ والجغرافية.\r\n\r\nستسهم هذه المحاور الموضوعاتية والمنهجية في دعم البحث العلمي في مجال الآداب والعلوم الإنسانية ذات الصلة بالقضايا الراهنة (البيئية والاقتصادية والاجتماعية والأدبية واللغوية…)\r\n\r\nإن تكوين الدكتوراه “المجال والتاريخ واللغات والآداب” مجال لتكوين طلبة الدكتوراه في الكلية متعددة التخصصات بتازة؛ وعليه فيستقطب أساسا الطلبة الباحثين الذي ينوون إعداد بحوثهم في حقل الدراسات الأدبية واللسانية ومجالي التاريخ والجغرافيا. وهو يتضمن عددا من محاور البحث الجديرة بفتح أفقهم على جديد المجالات التي يرتبط بها الأساتذة الباحثون المؤطرون في مختبري الكلية المعنيين، أي مختبر البحث في “اللغة والأدب والترجمة” ومختبر البحث في “المجال والتاريخ والدينامية والتنمية المستدامة”. هذا ويقترح هذا التكوين في الدكتوراه المحاور التكوينية الكبرى التالية:\r\n\r\nالمجتمع والدولة في تاريخ المغرب: البنيات والتحولات\r\nدينامية الأوساط الطبيعية والأخطار والتهيئة\r\nإعداد التراب وتدبير المجال\r\nالرقمنة وتحليل المعطيات والجيوماتيك\r\nالدراسات اللسانية بالعربية\r\nالدراسات الأدبية بالعربية\r\nالدراسات اللسانية بالفرنسية \r\nالدراسات الأدبية بالفرنسية\r\nالترجمة والتواصل والإعلام', 'jaouad.bouarfa@usmba.ac.ma', '2021-01-01', NULL),
(14, 'Sciences économiques et Gestion', 'La formation doctorale en sciences économiques et de gestion résulte de la volonté commune de trois laboratoires de recherche. Ce projet s’inscrit dans le contexte de l’ouverture de l’Université sur son environnement socio-économique.\r\nLa formation doctorale en Sciences Economiques et de gestion est destinée aux lauréats des masters ayant reçu une formation spécialisée dans différentes disciplines et notamment en Sciences Economiques et Gestion. Elle cherche à former des spécialistes de haut niveau capables d’enrichir le corps enseignant et les hauts cadres des administrations publiques et privées.', 'ahmed.azougagh@usmba.ac.ma', '2021-01-01', NULL),
(15, 'Droit Public', 'يهتم التكوين بمختلف المجالات والحقول المعرفية ذات الصلة بالقانون العام، منها القانون الدستوري والعلوم السياسية، والقانون المالي والقضاء المالي، والضرائب والجبايات المحلية، والقانون الإداري، والقانون الدولي والعلاقات الدولية. وحقوق الإنسان والحريات الأساسية.', 'ahmed.azougagh@usmba.ac.ma', '2021-01-01', NULL),
(16, 'Droit privé', 'Cette formation a pour objet d’animer la recherche et la formation en droit privé et ses différentes branches. Elle ambitionne de mener ces recherches et formations en partenariat avec les professionnels et les entreprises de la région.\r\n\r\nLes thématiques qui structurent les activités de cette formation sont en relation avec le droit privé. C’est une branche du droit traitant des règles juridiques relatives aux personnes physiques et morales dans une sphère privé. Plus précisément, il régit des relations entre les personnes agissant dans le secteur privé en relation avec les thèmes ci-dessus. Cette branche de droit se distingue du droit public qui réglemente les rapports entre l’État ou l’administration avec les particuliers, ainsi que les relations entre les institutions publiques. Par ailleurs, le droit privé est un domaine législatif vaste regroupant une multitude de disciplines.\r\n\r\nCette formation est épaulée par deux laboratoires qui regroupent une soixantaine d’enseignants chercheurs et des professionnels.\r\n\r\nElle constitue également la structure d’appui des étudiants qui préparent un master en droit privé ou droit économique en général. Il s’agit notamment des masters : droit notarial, contentieux des affaires, juriste d’affaires et droit international des affaires', 'ahmed.azougagh@usmba.ac.ma', '2021-01-01', NULL),
(17, 'Etudes juridiques politiques et économiques', 'يهدف هذا التكوين في الدكتوراه لتخريج كوكبة من حملة شهادة الدكتوراه في الحقول المعرفية التي تنتسب له بالكلية متعددة التخصصات بتازة، وهي في كليتها ترتد لحقول القانون العام، والقانون الخاص، والعلوم السياسية، والعلوم الاقتصادية، وعلوم التدبير.\r\nومجمل هذه الحقول المعرفية تعتبر ذات أهمية قصوى في إرداف القطاعين العام والخاص بخريجين متميزين يعدون قيمة مضافة للبحث العلمي العالي ببلادنا.\r\nLa formation doctorale a pour vocation première d’offrir aux doctorants une formation permettant l’acquisition et la consolidation des connaissances et compétences propres aux métiers de la recherche. La dite formation apporte un appui épistémologique, méthodologique et théorique assuré par les enseignants chercheurs de l’université Sidi Mohamed Ben Abdellah, des personnalités d’autres institutions ainsi que des professeurs invités internationaux. Le programme contribue ainsi à offrir un environnement favorable et un appui significatif pour la réalisation de la thèse et s’inscrit dans une logique de développement national et international.\r\nLe programme de la formation doctorale permet à chaque doctorant d’acquérir des « compétences professionnelles et scientifiques de haut niveau » dans le but de se spécialiser dans son domaine, de mener à bien ses recherches et de développer sa propre valeur sur le marché de l’emploi.\r\n\r\nLe Doctorat en Sciences Juridiques, Politiques, Economiques et de gestion est articulé autour de cinq axes : le Droit public, le Droit Privé, les Sciences Politiques, la Gestion et les Sciences Economiques.\r\nCes formations sont axées sur des champs de recherche qui couvrent entre autres : l’économie du développement, l’économie internationale, la théorie des jeux, l’économie de la santé, l’économie de l’énergie, l’économie financière, l’économie des territoires, l’économie publique, la macroéconomie, la micro-économie, le Management, la Finance, l’Audit, le Marketing, le Contrôle de gestion, la Gestion des Ressources humaines, Les Technologies d’affaires, l’Entreprenariat', 'jaoua@gmail.com', '2021-01-01', '0000-00-00'),
(18, 'Management des Organisations', 'La formation doctorale est axée sur le Management des Organisations au sens large. Elle permet d’approfondir le ou les domaines d’étude par la recherche, d’enrichir et de diversifier les compétences des doctorants dans les domaines de la gestion, du commerce et du management.\r\n\r\nCette formation doctorale cible en priorité les meilleurs lauréats des établissements universitaires en leur permettant de s’engager dans des problématiques de recherche prioritaires pour la région comme pour le pays.\r\n\r\nLa formation doctorale crée des passerelles avec l’entreprise et l’administration publique et permet aux chercheurs de répondre à leurs besoins et contribuer ainsi à leur développement.\r\n\r\nElle permet de contribuer au développement de la recherche aussi bien pure qu’appliquée dans le domaine du management des organisations et favoriser ainsi la performance des organisations afin de relancer l’économie marocaine tout en participant activement à la réalisation du nouveau modèle de développement au Maroc.', 'mili@gmail.com', '2021-01-01', '0000-00-00'),
(19, 'الشريعة والقانون وقضايا المجتمع', 'وُضع تكوين “الشريعة والقانون وقضايا المجتمع” أساسا للدراسة والبحث في نطاق الدكتوراه هذا.\r\nوتفرع عليه أمران تستدعي الحالة الراهنة للدراسات الشرعية عموما الاهتمام المتزامن والمنسق بهما في نفس الآن، وهما:\r\n• الفرع الاول : ” الأصالة” وذلك:\r\nبالحفاظ على الخصوصية المغربية التي يشكل الفقه المالكي أساسها الضارب في جذور التاريخ. وبالاستفادة من التراث العلمي في الفقه المالكي باعتباره من أهم المدارس الفقهية تطورا في سائر معارف العلوم الشرعية.\r\nوذلك على أساس الاستفادة من جميع الآليات التراثية التي يعتمدها الفقيه في تأصيل القول الفقهي والاستدلال عليه وكذا مقارنته.\r\n• الفرع الثاني: هو ” التجديد”\r\nبمراعاة المستجدات التي تقتضي مجهودا كبيرا للضبط العلمي بمختلف آلياتها المعتبرة أكاديميا. وذلك من أجل الانتقال من فقه تاريخي كان يلائم حاجات عصره، إلى فقه واقعي تنزيلي: يلبي الاحتياجات المعاصرة، ويتفتح على مدارس العلوم الشرعية والقانونية في شرق العالم الإسلامي وغربه، وينفتح على الثقافة الإنسانية عموما من أجل الاستفادة والإفادة، ولا يكون ذلك إلا بحوار فكري متسامح.\r\nويشير الفرع الثاني أي ” التجديد ” كذلك إلى ضبط الاشتغالات العلمية الرامية إلى تحديث آليات الفقيه. فإن الفقيه مطالب بالاستفادة من الإمكانات المتاحة في العصر الحالي، والمعتمدة على التطور التكنولوجي في المعلوميات ووسائل التواصل؛ ولكن هذه الاستفادة ينبغي لها أن تضبط في النطاق الأكاديمي بالضبط العلمي اللازم.\r\nولاتظر إلى مجموع المحاور التي يسترد إليها التكوين وعلى الرغم من تنوع تخصصاتها فإن مضامينها و نتائجها منسجمة مع عنوان التكوين والمحاور المشكلة له.\r\nهذا ولإحاطة فإن الفقه الإسلامي ينقسم إلى قسمين منصوص ومستنبط: ومهمة الفقيه بالنسبة للمنصوصات هي تخريج دلالاتها. وأما المستنبطات فإن الفقيه هو من يستنبطها بناء على تقنيات الاجتهاد المعروفة عند أهلها. وعملية التأصيل هي جوهر هذه العمليات كلها، وهي التي تضمن تجديد الفروع الشرعية وفق ما يتجدد من الظروف الواقعية.\r\nوبناء على هاتين المقدمتين، وفضلا عن الهدف العام المتمثل في الرقي بالمهارات الخاصة بخدمة العلوم الشرعية والقانونية؛ فإنه يمكن تلخيص الأهداف الموضوعية لهذا التكوين في أمرين:\r\nالأول: هو صقل المهارات التي يتوقف عليها تحرير الأحكام الفقهية، وتوثيق أدلتها.\r\nوالثاني: هو الرقي بالمهارات الدقيقة المتعلقة بأعمال التأصيل، وذلك من خلال:\r\n– ضبط المصطلحات والقواعد الأصولية، لتنضبط بذلك مفاهيم وأغراض الاستنباط.\r\n– تحرير القواعد الفقهية التي تكتنز التفريعات التشريعية.\r\n– التمرس بعملية التأصيل مع الاستفادة من جهود السابقين الموافقين والمخالفين، والانفتاح على مختلف التجارب التشريعية والحقوقية.', 'abd@gmail.com', '2021-01-01', '0000-00-00');
